package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

type MInt struct {
	x int64
}

func NewMInt(x int64) MInt {
	x %= MOD
	if x < 0 {
		x += MOD
	}
	return MInt{x: x}
}

func (a MInt) Add(b MInt) MInt {
	x := a.x + b.x
	if x >= MOD {
		x -= MOD
	}
	return MInt{x: x}
}

func (a MInt) Sub(b MInt) MInt {
	x := a.x - b.x
	if x < 0 {
		x += MOD
	}
	return MInt{x: x}
}

func (a MInt) Mul(b MInt) MInt {
	return MInt{x: (a.x * b.x) % MOD}
}

func modPow(x, y int64) int64 {
	res := int64(1)
	for y > 0 {
		if y&1 == 1 {
			res = (res * x) % MOD
		}
		x = (x * x) % MOD
		y >>= 1
	}
	return res
}

func modInv(x int64) int64 {
	return modPow(x, MOD-2)
}

func (a MInt) Div(b MInt) MInt {
	return MInt{x: (a.x * modInv(b.x)) % MOD}
}

func Zero() MInt {
	return MInt{x: 0}
}

type PrimeTable struct {
	table []uint32
}

func NewPrimeTable(maxN uint32) *PrimeTable {
	table := make([]uint32, (maxN+1)/2)
	for i := range table {
		table[i] = 1
	}
	table[0] = 0
	for i := uint32(3); ; i += 2 {
		i2 := i * i
		if i2 > maxN {
			break
		}
		if table[i>>1] == 1 {
			for j := i2; j <= maxN; j += i * 2 {
				if table[j>>1] == 1 {
					table[j>>1] = i
				}
			}
		}
	}
	return &PrimeTable{table: table}
}

func (pt *PrimeTable) forEach(n uint32, f func(uint32, uint32)) {
	k := uint32(0)
	for (n & (1 << k)) == 0 {
		if n>>k == 0 {
			break
		}
		k++
	}
	if k > 0 {
		f(2, k)
	}
	n >>= k
	for n > 1 && pt.table[n>>1] > 1 {
		p := pt.table[n>>1]
		cnt := uint32(1)
		n /= p
		for n > 1 && pt.table[n>>1] == p {
			n /= p
			cnt++
		}
		if n == p {
			cnt++
			n /= p
		}
		f(p, cnt)
	}
	if n > 1 {
		f(n, 1)
	}
}

func (pt *PrimeTable) CountDivisors(n uint32) uint32 {
	divisorCnt := uint32(1)
	pt.forEach(n, func(_ uint32, cnt uint32) {
		divisorCnt *= cnt + 1
	})
	return divisorCnt
}

