	var n int
	fmt.Fscan(in, &n)

	pt := NewPrimeTable(uint32(n))
	ans := Zero()
	acc := Zero()
	for i := 1; i <= n; i++ {
		c := pt.CountDivisors(uint32(i))
		ans = acc.Add(NewMInt(int64(c)))
		acc = acc.Add(ans)
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans.x)
	out.Flush()
}

